#!/usr/bin/env bash
set -Eeuo pipefail

VERSION="2.6.0"
APP_VERSION="NOVA-2.6.0-CLEAN-RUNTIME"
REV="2.6.0-CLEAN-RUNTIME-R1"
ZIP_NAME="QUANT_NOVA_2.6.0_CLEAN_RUNTIME_R1.zip"
EXPECTED_ZIP_SHA256="ad99b7cb58065578c577a8b0354c5ae6b0f45b46443794750ab94d47b60c53a1"
APP_DIR="${HOME}/quant-nova"
CONTAINER="quant-nova"
GUARD_CONTAINER="nova-http-guard"
CADDY_CONTAINER="kiwoom-caddy"
IMAGE="quant-nova:2.6.0-clean-runtime-r1-${EXPECTED_ZIP_SHA256:0:12}"
STAMP="$(date +%Y%m%d%H%M%S)"
BACKUP="quant-nova-backup-260-r1-${STAMP}"
FAILED="quant-nova-failed-260-r1-${STAMP}"
CANDIDATE="quant-nova-candidate-260-r1-${STAMP}"
TMP="$(mktemp -d)"
DEPLOY_DIR="${APP_DIR}/deployments/260-r1-${STAMP}"
LOCK_FILE="${APP_DIR}/.deploy.lock"
CAND_MEM="${NOVA_CANDIDATE_MEMORY:-420m}"
ACTIVE_MEM="${NOVA_ACTIVE_MEMORY:-600m}"
ACTIVE_RSS_HARD_MB="${NOVA_ACTIVE_RSS_HARD_MB:-540}"
FINAL_SOAK_SECONDS="${NOVA_FINAL_SOAK_SECONDS:-300}"
CANDIDATE_SOAK_SECONDS="${NOVA_CANDIDATE_SOAK_SECONDS:-45}"
SUCCESS=0
OLD_STOPPED=0
OLD_RENAMED=0
NEW_STARTED=0
GUARD_SYNCED=0

say(){ printf '\n==> %s\n' "$*"; }
fatal(){ echo "ERROR: $*" >&2; exit 1; }

mkdir -p "$APP_DIR" "$DEPLOY_DIR"
exec 9>"$LOCK_FILE"
flock -n 9 || fatal "another NOVA deployment is already running"

on_exit(){
  ec=$?
  trap - EXIT
  sudo docker rm -f "$CANDIDATE" >/dev/null 2>&1 || true
  if [[ $SUCCESS -ne 1 ]]; then
    echo "[AUTO-ROLLBACK] deployment did not seal; restoring previous active container" >&2
    if [[ $NEW_STARTED -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
      sudo docker stop -t 8 "$CONTAINER" >/dev/null 2>&1 || sudo docker kill "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker rename "$CONTAINER" "$FAILED" >/dev/null 2>&1 || true
    fi
    if [[ $OLD_RENAMED -eq 1 ]] && sudo docker inspect "$BACKUP" >/dev/null 2>&1; then
      sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
      sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
    elif [[ $OLD_STOPPED -eq 1 ]] && sudo docker inspect "$CONTAINER" >/dev/null 2>&1; then
      sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
    fi
    if [[ $GUARD_SYNCED -eq 1 && -d "$DEPLOY_DIR/guard-static-before" && -d "$APP_DIR/http-guard-v2/static" ]]; then
      sudo rm -rf "$APP_DIR/http-guard-v2/static"/* >/dev/null 2>&1 || true
      sudo cp -a "$DEPLOY_DIR/guard-static-before"/. "$APP_DIR/http-guard-v2/static"/ >/dev/null 2>&1 || true
      sudo rm -f "$APP_DIR/http-guard-v2/cache"/* >/dev/null 2>&1 || true
    fi
  fi
  rm -rf "$TMP" >/dev/null 2>&1 || true
  [[ $SUCCESS -eq 1 ]] && exit 0 || exit "${ec:-1}"
}
trap on_exit EXIT

say "1/10 Preflight — immutable previous active is preserved"
command -v sudo >/dev/null || fatal "sudo missing"
command -v python3 >/dev/null || fatal "python3 missing"
command -v sha256sum >/dev/null || fatal "sha256sum missing"
command -v unzip >/dev/null || fatal "unzip missing"
command -v docker >/dev/null || fatal "docker missing"
sudo docker info >/dev/null || fatal "docker daemon unavailable"
sudo docker inspect "$CONTAINER" >/dev/null 2>&1 || fatal "existing quant-nova container is required for rollback/environment preservation"
mkdir -p "$APP_DIR/data" "$APP_DIR/deployments"
FREE_MB=$(df -Pm "$APP_DIR" | awk 'NR==2{print $4}')
[[ ${FREE_MB:-0} -ge 900 ]] || fatal "need at least 900MB free disk; available=${FREE_MB:-0}MB"

OLD_IMAGE=$(sudo docker inspect -f '{{.Config.Image}}' "$CONTAINER")
NETWORK=$(sudo docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$CONTAINER" | head -1 | tr -d '[:space:]')
[[ -n "$NETWORK" ]] || NETWORK="bridge"
HOST_PORT=$(sudo docker inspect -f '{{(index (index .HostConfig.PortBindings "8000/tcp") 0).HostPort}}' "$CONTAINER" 2>/dev/null || true)
[[ -n "$HOST_PORT" ]] || HOST_PORT="3200"
DATA_SOURCE=$(sudo docker inspect -f '{{range .Mounts}}{{if eq .Destination "/app/data"}}{{.Source}}{{end}}{{end}}' "$CONTAINER")
[[ -n "$DATA_SOURCE" && -d "$DATA_SOURCE" ]] || fatal "cannot resolve existing /app/data mount"
RESTART_POLICY=$(sudo docker inspect -f '{{.HostConfig.RestartPolicy.Name}}' "$CONTAINER")
[[ -n "$RESTART_POLICY" && "$RESTART_POLICY" != "no" ]] || RESTART_POLICY="unless-stopped"

echo "OLD_IMAGE=$OLD_IMAGE"
echo "NETWORK=$NETWORK HOST_PORT=$HOST_PORT DATA_SOURCE=$DATA_SOURCE RESTART=$RESTART_POLICY"

# Preserve exact runtime environment, excluding values this installer intentionally controls.
sudo docker inspect -f '{{range .Config.Env}}{{println .}}{{end}}' "$CONTAINER" \
  | grep -Ev '^(PATH|HOSTNAME|HOME|PORT|NOVA_DATA_DIR|NOVA_CANDIDATE_MODE)=' > "$TMP/runtime.env" || true
chmod 600 "$TMP/runtime.env"

say "2/10 Extract embedded clean source + verify package SHA"
awk 'f{print} /^__NOVA_PAYLOAD_BELOW__$/{f=1}' "$0" | base64 -d > "$TMP/$ZIP_NAME"
GOT_ZIP_SHA=$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')
[[ "$GOT_ZIP_SHA" == "$EXPECTED_ZIP_SHA256" ]] || fatal "embedded zip sha mismatch: $GOT_ZIP_SHA"
unzip -t "$TMP/$ZIP_NAME" >/dev/null || fatal "embedded zip integrity failed"
unzip -q "$TMP/$ZIP_NAME" -d "$TMP/src"
ROOT="$TMP/src/nova2600"
[[ -f "$ROOT/Dockerfile" && -f "$ROOT/app/main.py" ]] || fatal "invalid source root"
(cd "$ROOT" && python3 scripts/build_context_check.py --mode package)
python3 -m compileall -q "$ROOT/app" "$ROOT/scripts"
cp "$TMP/$ZIP_NAME" "$DEPLOY_DIR/$ZIP_NAME"
sha256sum "$DEPLOY_DIR/$ZIP_NAME" > "$DEPLOY_DIR/$ZIP_NAME.sha256"

say "3/10 Quiesce previous active before build — prevents 1GB active+build swap storm"
sudo docker stop -t 12 "$CONTAINER" >/dev/null || sudo docker kill "$CONTAINER" >/dev/null
OLD_STOPPED=1
sleep 2
AVAILABLE_MB=$(free -m | awk '/Mem:/{print $7}')
echo "MEM_AVAILABLE_AFTER_OLD_STOP=${AVAILABLE_MB}MB"
[[ ${AVAILABLE_MB:-0} -ge 300 ]] || fatal "memory did not recover after stopping old active; available=${AVAILABLE_MB:-0}MB"

say "4/10 Freeze production data snapshot after active stop"
CAND_DATA="$TMP/candidate-data"
mkdir -p "$CAND_DATA"
sudo cp -a "$DATA_SOURCE"/. "$CAND_DATA"/ 2>/dev/null || fatal "production data snapshot failed"
sudo chown -R "$(id -u):$(id -g)" "$CAND_DATA" 2>/dev/null || true
DATA_BYTES=$(du -sb "$CAND_DATA" 2>/dev/null | awk '{print $1}')
echo "CANDIDATE_DATA_BYTES=${DATA_BYTES:-0}"

say "5/10 CLEAN Docker build — no docker commit, no running-source overwrite"
sudo docker build --pull=false -t "$IMAGE" "$ROOT"
IMAGE_ID=$(sudo docker image inspect -f '{{.Id}}' "$IMAGE")
echo "IMAGE=$IMAGE"
echo "IMAGE_ID=$IMAGE_ID"

say "6/10 Candidate with production-data copy + no-swap cap"
sudo docker run -d --name "$CANDIDATE" \
  --memory "$CAND_MEM" --memory-swap "$CAND_MEM" \
  --restart no --network none \
  --env-file "$TMP/runtime.env" \
  -e NOVA_CANDIDATE_MODE=1 -e NOVA_DATA_DIR=/app/data -e PORT=8000 \
  -v "$CAND_DATA:/app/data" \
  "$IMAGE" >/dev/null

probe_inside(){
  local path="$1"
  sudo docker exec "$CANDIDATE" python3 - "$path" <<'PY'
import json,sys,urllib.request
u='http://127.0.0.1:8000'+sys.argv[1]
r=urllib.request.urlopen(u,timeout=3);b=r.read();
if r.status!=200: raise SystemExit(2)
j=json.loads(b)
if j.get('ok') is False: raise SystemExit(3)
print(j.get('version') or j.get('status') or 'OK')
PY
}

for i in $(seq 1 60); do
  if probe_inside /api/livez >/dev/null 2>&1; then break; fi
  sleep 1
  [[ $i -lt 60 ]] || fatal "candidate livez did not start"
done
START_RESTART=$(sudo docker inspect -f '{{.RestartCount}}' "$CANDIDATE")
END=$((SECONDS+CANDIDATE_SOAK_SECONDS))
while (( SECONDS < END )); do
  probe_inside /api/livez >/dev/null || fatal "candidate livez failed"
  probe_inside /api/live-dashboard >/dev/null || fatal "candidate dashboard failed"
  probe_inside /api/realtime-health >/dev/null || fatal "candidate realtime health failed"
  OOM=$(sudo docker inspect -f '{{.State.OOMKilled}}' "$CANDIDATE")
  [[ "$OOM" == "false" ]] || fatal "candidate OOMKilled"
  sleep 3
done
END_RESTART=$(sudo docker inspect -f '{{.RestartCount}}' "$CANDIDATE")
[[ "$END_RESTART" == "$START_RESTART" ]] || fatal "candidate restarted"
CAND_PID=$(sudo docker inspect -f '{{.State.Pid}}' "$CANDIDATE")
CAND_SWAP_KB=$(sudo awk '/^VmSwap:/{print $2+0}' "/proc/$CAND_PID/status" 2>/dev/null || echo 0)
CAND_RSS_KB=$(sudo awk '/^VmRSS:/{print $2+0}' "/proc/$CAND_PID/status" 2>/dev/null || echo 0)
[[ ${CAND_SWAP_KB:-0} -eq 0 ]] || fatal "candidate process swap detected ${CAND_SWAP_KB}KB"
echo "CANDIDATE_SOAK=PASS RSS_KB=$CAND_RSS_KB VMSWAP_KB=$CAND_SWAP_KB"
sudo docker stop -t 5 "$CANDIDATE" >/dev/null || true
sudo docker rm "$CANDIDATE" >/dev/null || true

say "7/10 Atomic cutover — previous container becomes immutable rollback backup"
sudo docker rename "$CONTAINER" "$BACKUP"
OLD_RENAMED=1
OLD_STOPPED=0
sudo docker run -d --name "$CONTAINER" \
  --memory "$ACTIVE_MEM" --memory-swap "$ACTIVE_MEM" \
  --restart "$RESTART_POLICY" --network "$NETWORK" \
  --env-file "$TMP/runtime.env" \
  -e NOVA_CANDIDATE_MODE=0 -e NOVA_DATA_DIR=/app/data -e PORT=8000 \
  -p "127.0.0.1:${HOST_PORT}:8000" \
  -v "$DATA_SOURCE:/app/data" \
  "$IMAGE" >/dev/null
NEW_STARTED=1

host_probe(){
  local path="$1"
  python3 - "$HOST_PORT" "$path" <<'PY'
import json,sys,urllib.request
u=f'http://127.0.0.1:{sys.argv[1]}{sys.argv[2]}'
r=urllib.request.urlopen(u,timeout=4);b=r.read()
if r.status!=200: raise SystemExit(2)
j=json.loads(b)
if j.get('ok') is False: raise SystemExit(3)
print(j.get('version') or j.get('status') or 'OK')
PY
}

for i in $(seq 1 90); do
  if host_probe /api/livez >/dev/null 2>&1; then break; fi
  sleep 1
  [[ $i -lt 90 ]] || fatal "new active livez did not start"
done

say "8/10 Final active full-worker soak ${FINAL_SOAK_SECONDS}s"
START_RESTART=$(sudo docker inspect -f '{{.RestartCount}}' "$CONTAINER")
RSS_BASE=0; RSS_LAST=0; RSS_MAX=0; SAMPLE_N=0
END=$((SECONDS+FINAL_SOAK_SECONDS))
while (( SECONDS < END )); do
  host_probe /api/livez >/dev/null || fatal "final livez failed"
  host_probe /api/live-dashboard >/dev/null || fatal "final dashboard failed"
  host_probe /api/realtime-health >/dev/null || fatal "final realtime-health failed"
  OOM=$(sudo docker inspect -f '{{.State.OOMKilled}}' "$CONTAINER")
  [[ "$OOM" == "false" ]] || fatal "final active OOMKilled"
  PID=$(sudo docker inspect -f '{{.State.Pid}}' "$CONTAINER")
  [[ ${PID:-0} -gt 1 ]] || fatal "final active PID unavailable"
  RSS_KB=$(sudo awk '/^VmRSS:/{print $2+0}' "/proc/$PID/status" 2>/dev/null || echo 0)
  SWAP_KB=$(sudo awk '/^VmSwap:/{print $2+0}' "/proc/$PID/status" 2>/dev/null || echo 0)
  [[ ${SWAP_KB:-0} -eq 0 ]] || fatal "final process VmSwap detected ${SWAP_KB}KB"
  RSS_MB=$((RSS_KB/1024)); (( RSS_MB > RSS_MAX )) && RSS_MAX=$RSS_MB
  SAMPLE_N=$((SAMPLE_N+1)); [[ $SAMPLE_N -eq 5 ]] && RSS_BASE=$RSS_MB
  RSS_LAST=$RSS_MB
  [[ $RSS_MB -le $ACTIVE_RSS_HARD_MB ]] || fatal "final RSS hard gate exceeded ${RSS_MB}MB > ${ACTIVE_RSS_HARD_MB}MB"
  sleep 5
done
END_RESTART=$(sudo docker inspect -f '{{.RestartCount}}' "$CONTAINER")
[[ "$END_RESTART" == "$START_RESTART" ]] || fatal "final active restarted during soak"
# When the market session itself is active, a healthy HTTP process is not enough: the broker WS
# must also be connected and have active registrations. Outside an active session this gate is skipped.
python3 - "$HOST_PORT" <<'PYFEED' || fatal "final active broker-feed gate failed"
import json,sys,urllib.request
j=json.loads(urllib.request.urlopen(f'http://127.0.0.1:{sys.argv[1]}/api/live-dashboard',timeout=4).read())
feed=j.get('feed') or {}; sess=feed.get('session') or {}; ws=((j.get('health') or {}).get('ws') or {})
if sess.get('active'):
    assert ws.get('connected') is True, {'feed':feed,'ws':ws}
    assert int(ws.get('registered_codes') or 0)>0 or int(ws.get('trade_registered') or 0)>0, {'feed':feed,'ws':ws}
    assert feed.get('state') in ('LIVE','CONNECTED_WAITING_TICK'), {'feed':feed,'ws':ws}
print('BROKER_FEED_GATE=PASS',feed.get('state'),'registered',ws.get('registered_codes'))
PYFEED
if [[ $RSS_BASE -gt 0 ]]; then
  RSS_GROWTH=$((RSS_LAST-RSS_BASE))
  [[ $RSS_GROWTH -le 100 ]] || fatal "final RSS still growing excessively: +${RSS_GROWTH}MB"
else RSS_GROWTH=0; fi
echo "FINAL_SOAK=PASS RSS_BASE_MB=$RSS_BASE RSS_LAST_MB=$RSS_LAST RSS_MAX_MB=$RSS_MAX RSS_GROWTH_MB=$RSS_GROWTH"

say "9/10 Public UI atomic sync only after runtime PASS"
GUARD_STATIC="$APP_DIR/http-guard-v2/static"
GUARD_CACHE="$APP_DIR/http-guard-v2/cache"
if [[ -d "$GUARD_STATIC" ]]; then
  mkdir -p "$DEPLOY_DIR/guard-static-before"
  sudo cp -a "$GUARD_STATIC"/. "$DEPLOY_DIR/guard-static-before"/ 2>/dev/null || true
  for f in index.html nova.js nova.css sw.js manifest.webmanifest icon-192.png icon-512.png; do
    [[ -f "$ROOT/static/$f" ]] || continue
    sudo cp "$ROOT/static/$f" "$GUARD_STATIC/.$f.260.tmp"
    sudo chmod 644 "$GUARD_STATIC/.$f.260.tmp"
    sudo mv "$GUARD_STATIC/.$f.260.tmp" "$GUARD_STATIC/$f"
  done
  sudo rm -f "$GUARD_CACHE"/* >/dev/null 2>&1 || true
  GUARD_SYNCED=1
fi
host_probe /api/livez >/dev/null || fatal "post-static-sync livez failed"

say "10/10 Deployment seal"
cat > "$DEPLOY_DIR/DEPLOYMENT_OK.txt" <<EOFSEAL
status=PASS
version=$APP_VERSION
rev=$REV
source_zip_sha256=$EXPECTED_ZIP_SHA256
image=$IMAGE
image_id=$IMAGE_ID
old_image=$OLD_IMAGE
rollback_backup=$BACKUP
candidate_memory=$CAND_MEM
active_memory=$ACTIVE_MEM
candidate_soak_seconds=$CANDIDATE_SOAK_SECONDS
final_soak_seconds=$FINAL_SOAK_SECONDS
final_rss_base_mb=$RSS_BASE
final_rss_last_mb=$RSS_LAST
final_rss_max_mb=$RSS_MAX
final_rss_growth_mb=$RSS_GROWTH
final_vmswap_kb=0
build_model=CLEAN_DOCKER_BUILD_NO_COMMIT_NO_HOTPATCH
signal_policy=BUY_PARITY_FROZEN
completed_at=$(date -Is)
EOFSEAL
SUCCESS=1
NEW_STARTED=0
printf '\n=== NOVA 2.6 CLEAN RUNTIME DEPLOY PASS ===\n'
printf 'BACKUP_PRESERVED=%s\n' "$BACKUP"
printf 'DEPLOYMENT_SEAL=%s\n' "$DEPLOY_DIR/DEPLOYMENT_OK.txt"
exit 0

__NOVA_PAYLOAD_BELOW__
